typedef void (* Fiq_Func)(void) ;

typedef void (* volatile Hi_Pri_Func)(void) ;

//--------------------------------------------------------------------------//

typedef enum
{
	FIQ_TC_TIMER_1,
	FIQ_TC_TIMER_2,
	FIQ_TC_TIMER_3,
	
	FIQ_TC_ENUM_COUNT 	

} Fiq_Tc_Enum ;

//--------------------------------------------------------------------------//

#define FIQ_CRITICAL	int __fiq_crit_var__

#define FIQ_ENTER  	 {      __fiq_crit_var__ = __disable_fiq () ; } while (0)    
#define FIQ_LEAVE  	 { if (!__fiq_crit_var__)  __enable_fiq  () ; } while (0)    

#define ATOMIC_FIQ(__zzz__) { FIQ_CRITICAL ; FIQ_ENTER ; { __zzz__ ; } FIQ_LEAVE ; }

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
