Boolean fiq_unregister      (Fiq_Func fiq_func)         ;
UInt32  fiq_get_tc	   	    (Fiq_Tc_Enum fiq_tc_enum)   ;

Boolean fiq_register_hi_pri (Hi_Pri_Func func)          ; 

